function monotoneIncreasingDigits(n) {
  // Enumerate every monotone number up to n by appending digits that never go down.
  let best = 0;
  const grow = (value, last) => {
    if (value > n) return;
    if (value > best) best = value;
    for (let d = last; d <= 9; d++) grow(value * 10 + d, d);
  };
  for (let d = 1; d <= 9; d++) grow(d, d);
  return best;
}

