function generate(rand, size) {
  const pick = (k) => Math.floor(rand() * k);
  if (size === 'large') {
    const length = 7 + pick(3);
    let text = String(1 + pick(9));
    for (let i = 1; i < length; i++) text += String(pick(10));
    if (rand() < 0.2) return [1000000000];
    return [Number(text)];
  }
  const mode = pick(4);
  if (mode === 0) return [pick(1000)];
  const length = 1 + pick(6);
  // Draw digits from a narrow band so equal neighbours and small drops are common.
  const low = pick(9);
  const span = 1 + pick(3);
  let text = String(Math.max(1, Math.min(9, low + pick(span))));
  for (let i = 1; i < length; i++) {
    text += String(mode === 1 ? pick(10) : Math.min(9, low + pick(span)));
  }
  return [Number(text)];
}
